export const TRICK_KEY = "sea_urchin";
export const TRICKS = ["spinewalk", "lanterngraze", "gripcreep", "spineflare", "pedicellaria", "aristotle", "strongylhush"] as const;
export const HAPPY = ["densurchin", "inkthorn", "densstrongyl"] as const;
export type SeaUrchinTrickKind = (typeof TRICKS)[number];
export type SeaUrchinHappyKind = (typeof HAPPY)[number];
export type TrickAnim = "idle" | "walk" | "sit" | "sleep" | "talk" | "play";
export type TrickPhase = "go" | "hold" | "release" | "done";
export type HappyPhase = "go" | "done";

export type TrickFlags = {
  asleep?: boolean;
  hidden?: boolean;
  leaving?: boolean;
  cmd?: string;
  windowPlay?: boolean;
  card?: boolean;
};

export type SeaUrchinTrick = {
  kind: SeaUrchinTrickKind;
  phase: TrickPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export type SeaUrchinHappy = {
  kind: SeaUrchinHappyKind;
  happy: true;
  phase: HappyPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export const HAPPY_DUR = { densurchin: 1.70, inkthorn: 1.84, densstrongyl: 1.76 } as const;
export const STRONGYLHUSH_HOLD = 11.2;
export const RELEASE_S = 1.18;
export const DUR = {
  strongylhush: STRONGYLHUSH_HOLD + RELEASE_S,
  spinewalk: 2.48,
  lanterngraze: 2.42,
  gripcreep: 2.40,
  spineflare: 2.44,
  pedicellaria: 2.38,
  aristotle: 2.56,
} as const;

export function canStart(state: TrickFlags | undefined) {
  if (!state) return false;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return false;
  const cmd = String(state.cmd || "");
  if (cmd === "sleep" || cmd === "leave" || cmd === "hide" || cmd === "rest") return false;
  if (cmd === "seek" || cmd === "eat" || cmd === "play" || cmd === "talk" || cmd === "enter") return false;
  return true;
}

export function shouldAbort(state: TrickFlags | undefined) {
  if (!state) return true;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return true;
  const cmd = String(state.cmd || "");
  return (
    cmd === "sleep" ||
    cmd === "leave" ||
    cmd === "hide" ||
    cmd === "rest" ||
    cmd === "seek" ||
    cmd === "eat" ||
    cmd === "play" ||
    cmd === "talk" ||
    cmd === "enter"
  );
}

export function nextTrickWait(justFinished: boolean, rand?: number, kind?: SeaUrchinTrickKind | string) {
  const roll = rand == null ? Math.random() : rand;
  if (kind === "strongylhush") return 40 + roll * 26;
  if (kind === "pedicellaria" || kind === "spinewalk" || kind === "spineflare") return 12.8 + roll * 9.4;
  if (kind === "gripcreep" || kind === "lanterngraze" || kind === "aristotle") return 11.6 + roll * 8.5;
  return justFinished ? 8.5 + roll * 8.4 : 4.4 + roll * 7.4;
}

